def on_tick(t, state, api):
    if not state.get("open"):
        return
    tod = t % 86400
    if tod < 79200:
        return
    if state.get("notified"):
        return
    open_since = state.get("open_since", t)
    day_start = t - tod
    ten_pm = day_start + 79200
    effective = open_since
    if effective < ten_pm:
        effective = ten_pm
    if t - effective > 300:
        state["notified"] = True
        api.notify("Door has been open for more than 5 minutes after 10 pm.")
